21	impl ItemType {
22	    /// The MHPCO price-list row for a main item, or `None` for a component:
23	    /// components are not on the main price list, they are charged per type
24	    /// by `component_charge`.
25	    fn main_item_base_premium(self) -> Option<f64> {
26	        match self {
27	            Self::Sword => Some(100.0),
28	            Self::Amulet => Some(60.0),
29	            Self::Staff => Some(80.0),
30	            Self::Potion => Some(40.0),
31	            Self::Rune | Self::Moonstone => None,
32	        }
33	    }
