54	impl Item {
55	    pub fn new(item_type: ItemType) -> Self {
56	        Self {
57	            item_type,
58	            cursed: false,
59	            enchantment: 0,
60	        }
61	    }
62	
63	    /// The item's enchantment level, as recorded by the MHPCO.
64	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
65	        self.enchantment = enchantment;
66	        self
67	    }
68	
69	    /// A cursed item carries the MHPCO's risk surcharge.
70	    pub fn cursed(mut self) -> Self {
71	        self.cursed = true;
72	        self
73	    }
74	
75	    /// The item-specific risk surcharges this item carries, charged against the
76	    /// item's own base premium rather than the policy total. A component carries
77	    /// none: the MHPCO records no curse, enchantment or material for one, so it
78	    /// is never an affected item.
79	    fn item_surcharge(&self) -> f64 {
80	        match self.item_type.main_item_base_premium() {
81	            Some(item_base) => item_base * self.risk_surcharge_rate(),
82	            None => 0.0,
83	        }
84	    }
85	
86	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
87	    /// enchantment threshold when reimbursing damage, so this one is named for
88	    /// the premium it surcharges.
89	    fn is_highly_enchanted(&self) -> bool {
90	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
91	    }
92	
93	    /// Curse and high enchantment are independent risks; an item carrying both
94	    /// is surcharged for both.
95	    fn risk_surcharge_rate(&self) -> f64 {
96	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
97	        let enchantment = if self.is_highly_enchanted() {
98	            HIGH_ENCHANTMENT_SURCHARGE
99	        } else {
100	            0.0
101	        };
102	        curse + enchantment
103	    }
104	}
105	
106	const PROCESSING_FEE: u64 = 5;
107	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
108	/// Cursed items add a risk surcharge on their own base premium.
109	const CURSE_SURCHARGE: f64 = 0.50;
110	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
111	/// surcharge on their own base premium.
112	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
113	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
114	/// Components -- for example runes and moonstones -- share one price-list row.
115	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
116	
117	/// Premiums are rounded up: the MHPCO's favour is the larger amount.
118	fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
119	    amount.ceil() as u64
120	}
121	
122	/// The policy-wide modifier rate, charged against the policy base premium --
123	/// the sum of all item base premiums. The MHPCO reads one such modifier today:
124	/// a first insurance carries an initial assessment surcharge.
125	fn policy_modifier_rate(_customer: &Customer) -> f64 {
126	    FIRST_INSURANCE_SURCHARGE
127	}
128	
129	/// A building block of exactly 3 alike components is offered at this price
130	/// instead of the per-component base premium.
131	const COMPONENT_BLOCK_SIZE: usize = 3;
132	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
133	
134	/// Alike components -- components of the very same type -- are charged as a
135	/// block when there are exactly 3 of them.
136	const COMPONENT_TYPES: [ItemType; 2] = [ItemType::Rune, ItemType::Moonstone];
137	
138	fn component_charge(alike_count: usize) -> f64 {
139	    if alike_count == COMPONENT_BLOCK_SIZE {
140	        COMPONENT_BLOCK_BASE_PREMIUM
141	    } else {
142	        alike_count as f64 * COMPONENT_BASE_PREMIUM
143	    }
144	}
145	
146	/// How many of the policy's items are alike the given component type. Alike
147	/// components are the ones charged together, so this is where the MHPCO's
148	/// reading of "alike" lives.
149	fn alike_component_count(items: &[Item], component_type: ItemType) -> usize {
150	    items
151	        .iter()
152	        .filter(|item| item.item_type == component_type)
153	        .count()
154	}
155	
156	/// Main items are charged one price-list row each, individually.
157	fn main_items_base_premium(items: &[Item]) -> f64 {
158	    items
159	        .iter()
160	        .filter_map(|item| item.item_type.main_item_base_premium())
161	        .sum()
162	}
163	
164	/// Components are charged per group of alike components, so that a group of
165	/// exactly 3 earns the block price.
166	fn component_blocks_base_premium(items: &[Item]) -> f64 {
167	    COMPONENT_TYPES
168	        .iter()
169	        .map(|component_type| component_charge(alike_component_count(items, *component_type)))
170	        .sum()
171	}
172	
173	/// The policy base premium is the sum of the items' base premiums, with alike
174	/// components charged as blocks.
175	pub fn policy_base_premium(items: &[Item]) -> f64 {
176	    main_items_base_premium(items) + component_blocks_base_premium(items)
177	}
178	
179	/// Item-specific modifiers apply to the base premium of the affected item, not
180	/// to the policy total.
181	fn item_surcharges(items: &[Item]) -> f64 {
182	    items.iter().map(Item::item_surcharge).sum()
183	}
184	
185	pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
186	    let policy_base = policy_base_premium(items);
187	    let premium_before_fee = policy_base
188	        + policy_base * policy_modifier_rate(customer)
189	        + item_surcharges(items);
190	    round_premium_in_mhpco_favour(premium_before_fee) + PROCESSING_FEE
191	}
